class A {
    static String s() { return "A-static"; }
    String i() { return "A-inst"; }
}
class B extends A {
    static String s() { return "B-static"; }
    String i() { return "B-inst"; }
}
public class Main {
    public static void main(String[] args) {
        A x = new B();
        System.out.println(x.s());
        System.out.println(x.i());
    }
}

